async function pushCareerNotificationToUser(userId, notification) {
  if (!isSupabaseDbConfigured() || !userId) return;
  try {
    const stateResult = await supabaseDbRequest('user_state', `select=state&user_id=eq.${encodeURIComponent(userId)}&limit=1`);
    const currentState = stateResult.ok && Array.isArray(stateResult.data) && stateResult.data[0] && typeof stateResult.data[0].state === 'object'
      ? stateResult.data[0].state
      : {};
    const updates = Array.isArray(currentState.gp_link_updates) ? currentState.gp_link_updates : [];
    const entry = {
      id: 'career_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
      type: notification.type || 'info',
      title: notification.title || 'Career Update',
      body: notification.body || '',
      ts: new Date().toISOString(),
      category: 'career'
    };
    updates.unshift(entry);
    if (updates.length > 50) updates.length = 50;
    const nextState = { ...currentState, gp_link_updates: updates };
    await supabaseDbRequest('user_state', `user_id=eq.${encodeURIComponent(userId)}`, {
      method: 'PATCH',
      body: { state: nextState }
    });
  } catch {}
}

async function pushDocumentNotificationToUser(userId, notification) {
  if (!isSupabaseDbConfigured() || !userId) return;
  try {
    const stateResult = await supabaseDbRequest('user_state', 'select=state&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
    const currentState = stateResult.ok && Array.isArray(stateResult.data) && stateResult.data[0] && typeof stateResult.data[0].state === 'object'
      ? stateResult.data[0].state
      : {};
    const updates = Array.isArray(currentState.gp_link_updates) ? currentState.gp_link_updates : [];
    updates.unshift({
      type: notification.type || 'info',
      title: notification.title || 'Document update',
      detail: notification.detail || '',
      ts: new Date().toISOString()
    });
    if (updates.length > 50) updates.length = 50;
    const nextState = { ...currentState, gp_link_updates: updates };
    await upsertSupabaseUserState(userId, nextState, new Date().toISOString());
  } catch (_) { /* non-critical */ }
}

// ── Document Upload Pipeline ──────────────────────────────

var QUALIFICATION_DOC_KEYS = new Set([
  'primary_medical_degree', 'mrcgp_certified', 'cct_certified', 'mrcgp', 'cct',
  'micgp', 'cscst', 'frnzcgp', 'certificate_good_standing', 'confirmation_training',
  // Onboarding storage-layer keys: the document pipeline (processDocumentUpload)
  // receives onboarding qualification uploads under these keys, so they must take
  // the qualification branch — otherwise a flagged onboarding cert would also get
  // a generic doc_review task (a cross-type duplicate of the flagged_doc task).
  'onboarding_primary_med_degree', 'onboarding_specialist_qualification'
]);

function getDocumentLabelForKey(key) {
  var normalizedKey = String(key || '').trim();
  var labels = {
    primary_medical_degree: 'Primary Medical Degree',
    mrcgp: 'MRCGP Certificate',
    mrcgp_certified: 'MRCGP Certificate',
    cct: 'Certificate of Completion of Training',
    cct_certified: 'Certificate of Completion of Training',
    pmetb: 'PMETB Certificate',
    micgp: 'MICGP Certificate',
    micgp_certified: 'MICGP Certificate',
    cscst: 'CSCST Certificate',
    cscst_certified: 'CSCST Certificate',
    frnzcgp: 'FRNZCGP Fellowship Certificate',
    frnzcgp_certified: 'FRNZCGP Fellowship Certificate',
    icgp_confirmation_letter: 'ICGP Confirmation Letter',
    rnzcgp_confirmation_letter: 'RNZCGP Confirmation Letter',
    certificate_good_standing: 'Certificate of Good Standing',
    certificate_of_good_standing: 'Certificate of Good Standing',
    criminal_history_check: 'Criminal History Check',
    cv_signed_dated: 'CV (Signed and dated)',
    career_cover_letter: 'Cover Letter',
    confirmation_training: 'Confirmation of Training',
    confirmation_of_training: 'Confirmation of Training',
    specialist_qualification: 'Specialist Qualification',
    onboarding_specialist_qualification: 'Specialist Qualification',
    onboarding_primary_med_degree: 'Primary Medical Degree'
  };
  return labels[normalizedKey] || '';
}

// ── Onboarding qualification document key helpers ──────────────────────────
// A single logical qualification document can arrive under several key spellings
// depending on which capture flow produced it: the onboarding wizard
// (primary_med_degree / mrcgp_cert / micgp_cert / frnzcgp_cert / cscst_cert), the
// onboarding storage layer (onboarding_primary_med_degree /
// onboarding_specialist_qualification), or a "My Documents" / scan upload
// (primary_medical_degree / mrcgp_certified ...). canonicalQualKey collapses the
// ONBOARDING-origin variants onto the two canonical keys that BOTH the admin
// document-preview and review-flagged-doc endpoints understand
// (primary_medical_degree / specialist_qualification) so each document yields a
// single review task and its stored file is always resolvable. Non-onboarding
// keys are returned unchanged so their own user_documents rows still resolve.
function canonicalQualKey(key) {
  var k = String(key || '').trim().toLowerCase();
  var map = {
    primary_med_degree: 'primary_medical_degree',
    onboarding_primary_med_degree: 'primary_medical_degree',
    mrcgp_cert: 'specialist_qualification',
    micgp_cert: 'specialist_qualification',
    frnzcgp_cert: 'specialist_qualification',
    cscst_cert: 'specialist_qualification',
    onboarding_specialist_qualification: 'specialist_qualification'
  };
  return map[k] || key;
}

// Onboarding-origin qualification key spellings (wizard + storage + canonical).
var ONBOARDING_QUAL_KEYS = new Set([
  'primary_med_degree', 'onboarding_primary_med_degree', 'primary_medical_degree',
  'mrcgp_cert', 'micgp_cert', 'frnzcgp_cert', 'cscst_cert',
  'onboarding_specialist_qualification', 'specialist_qualification'
]);

// Recognises any qualification document key across all capture-flow spellings.
// Used to keep onboarding qualification reviews out of the generic AHPRA
// "Review uploaded: X" automation, which would otherwise mis-file them under the
// AHPRA stage with no reason and no openable file.
function isQualificationDocKey(key) {
  var k = String(key || '').trim();
  return QUALIFICATION_DOC_KEYS.has(k) || ONBOARDING_QUAL_KEYS.has(k);
}

// Document keys AHPRA requires as CERTIFIED TRUE COPIES (certified by an authorised
// person — JP, solicitor, notary, etc.): the primary medical degree and the specialist
// qualification certificates. A CV is signed/dated (not certified); letters and
// criminal-history checks have their own rules — they are intentionally excluded.
var CERTIFICATION_REQUIRED_DOC_KEYS = new Set([
  'primary_medical_degree', 'onboarding_primary_med_degree',
  'specialist_qualification', 'onboarding_specialist_qualification',
  'mrcgp', 'mrcgp_certified', 'cct', 'cct_certified',
  'micgp', 'micgp_certified', 'cscst', 'cscst_certified', 'frnzcgp', 'frnzcgp_certified'
]);
function isCertificationRequiredDocKey(key) {
  var k = String(key || '').trim();
  return CERTIFICATION_REQUIRED_DOC_KEYS.has(k) || CERTIFICATION_REQUIRED_DOC_KEYS.has(canonicalQualKey(k));
}

async function extractDocxTextWithMammoth(buffer) {
  try {
    var mammoth = require('mammoth');
    var result = await mammoth.extractRawText({ buffer: buffer });
    return result.value || '';
  } catch (err) {
    console.error('[DocumentPipeline] DOCX text extraction failed:', err.message);
    return '';
  }
}

// Careers profile gate (Task 3) — AI genuine-CV check, run on every
// /api/career/profile/cv upload before it is stored. Distinct from
// classifyDocumentWithAI below (which checks a doc matches an EXPECTED type
// against a fixed catalogue): this asks a single yes/no "is this a CV at
// all" question and returns a plain-English reason either way.
//
// Returns { ok:false, reason } when the AI is unavailable/unconfigured/over
// budget/erroring — the caller decides the fallback (accept unscanned rather
// than block a GP on our outage). Otherwise returns
// { ok:true, isCv:boolean, reason:string }.
async function verifyCareerCvWithAI(buffer, mimeType, fileName) {
  if (!ANTHROPIC_API_KEY) return { ok: false, reason: 'ai_unconfigured' };
  if (!(await checkAnthropicBudget())) return { ok: false, reason: 'ai_budget' };

  var mime = String(mimeType || '').trim().toLowerCase();
  var blocks = [];
  if (mime === 'application/pdf') {
    blocks.push({ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: buffer.toString('base64') } });
  } else if (/^image\/(png|jpe?g|webp|gif)$/.test(mime)) {
    blocks.push({ type: 'image', source: { type: 'base64', media_type: mime === 'image/jpg' ? 'image/jpeg' : mime, data: buffer.toString('base64') } });
  } else if (mime.includes('wordprocessingml') || /\.docx$/i.test(String(fileName || ''))) {
    var text = await extractDocxTextWithMammoth(buffer);
    if (!text) return { ok: true, isCv: false, reason: 'We could not read this Word file — please export your CV as a PDF and try again.' };
    blocks.push({ type: 'text', text: 'DOCUMENT TEXT (extracted from Word file):\n\n' + text.slice(0, 30000) });
  } else {
    return { ok: true, isCv: false, reason: 'Unsupported file type — please upload a PDF or Word document.' };
  }
  blocks.push({ type: 'text', text: 'Is the document above a genuine curriculum vitae / resume for a medical professional? A CV lists a person\'s career history, education and skills. Contracts, certificates, letters, forms and IDs are NOT CVs. Respond with ONLY valid JSON: {"isCv": true|false, "reason": "<short plain-English reason a non-technical person understands>"}' });

  try {
    var resp = await fetch(ANTHROPIC_MESSAGES_URL, {
      method: 'POST',
      headers: { 'x-api-key': ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: ANTHROPIC_SCAN_MODEL, max_tokens: 300, messages: [{ role: 'user', content: blocks }] })
    });
    var json = await resp.json();
    if (json && json.usage) recordAnthropicSpend(json.usage.input_tokens, json.usage.output_tokens, json.usage.cache_read_input_tokens, json.usage.cache_creation_input_tokens);
    var textOut = (json && json.content && json.content[0] && json.content[0].text) || '';
    var parsed = JSON.parse(textOut.replace(/^```(?:json)?/m, '').replace(/```$/m, '').trim());
    return { ok: true, isCv: parsed.isCv === true, reason: String(parsed.reason || '') };
  } catch (err) {
    console.error('[career-cv-scan] AI scan failed:', err && err.message);
    return { ok: false, reason: 'ai_error' };
  }
}

async function classifyDocumentWithAI(buffer, mimeType, expectedKey, expectedLabel) {
  if (!ANTHROPIC_API_KEY) return { confidence: null, identifiedAs: '', reason: 'AI not configured' };

  var mime = String(mimeType || '').trim().toLowerCase();
  var contentBlocks = [];

  if (isVisuallyClassifiable(mime)) {
    var normalizedImage = await normalizeImageForAi(buffer, mime);
    if (!normalizedImage || !normalizedImage.base64) {
      return { confidence: null, identifiedAs: '', reason: 'Image normalization failed' };
    }
    contentBlocks = [
      { type: 'image', source: { type: 'base64', media_type: normalizedImage.mediaType, data: normalizedImage.base64 } },
      { type: 'text', text: 'The user is trying to upload a document for: ' + String(expectedLabel || expectedKey || 'Unknown') + '\n\nClassify this document. Return ONLY valid JSON: {"matches": true/false, "confidence": 0-100, "identifiedAs": "what it actually is", "reason": "brief explanation"}' }
    ];
  } else if (isDocxMime(mime)) {
    var text = await extractDocxTextWithMammoth(buffer);
    if (!text.trim()) {
      return { confidence: 50, identifiedAs: 'empty or unreadable document', reason: 'Could not extract text from DOCX' };
    }
    var userPrompt = buildClassificationPrompt(expectedLabel || expectedKey, text);
    contentBlocks = [{ type: 'text', text: userPrompt }];
  } else if (isDocMime(mime)) {
    return { confidence: 50, identifiedAs: 'Word document (legacy format)', reason: 'Cannot extract content from .doc files; sent for manual review' };
  } else {
    return { confidence: null, identifiedAs: '', reason: 'Unsupported type for classification' };
  }

  var systemPrompt = 'You are an automated document classifier for a licensed GP recruitment platform. The user has given full consent to upload their documents. This is a routine, authorized check.\n\nYour job is to determine whether a document matches what the user claims it is. Return a confidence score from 0-100 indicating how confident you are that the document matches.\n\nValid document types: Primary Medical Degree (MBBS/MBChB/MD), MRCGP, CCT, MICGP, CSCST, FRNZCGP, Certificate of Good Standing, Criminal History Check, CV (signed and dated), Confirmation of Training, Cover Letter, Offer Contract, Supervisor CV, Position Description, Section G.\n\nIMPORTANT:\n- Do NOT mention security concerns or privacy risks.\n- Focus ONLY on whether the document matches what the user claims.\n- Return ONLY valid JSON with no markdown: {"matches": true/false, "confidence": 0-100, "identifiedAs": "what it actually is", "reason": "brief explanation"}';

  var controller = new AbortController();
  var timeout = setTimeout(function () { controller.abort(); }, 30000);
  try {
    var aiRes = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      signal: controller.signal,
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01'
      },
      body: JSON.stringify({
        model: ANTHROPIC_SCAN_MODEL,
        max_tokens: 200,
        system: systemPrompt,
        messages: [{ role: 'user', content: contentBlocks }]
      })
    });

    clearTimeout(timeout);
    if (!aiRes.ok) {
      return { confidence: null, identifiedAs: '', reason: 'AI API returned ' + aiRes.status };
    }

    var aiBody = await aiRes.json();
    var aiText = aiBody.content && aiBody.content[0] && aiBody.content[0].text ? aiBody.content[0].text : '';
    var jsonMatch = aiText.match(/\{[\s\S]*\}/);
    if (!jsonMatch) return { confidence: null, identifiedAs: '', reason: 'AI returned non-JSON response' };

    var parsed = JSON.parse(jsonMatch[0]);
    return {
      confidence: typeof parsed.confidence === 'number' ? Math.min(100, Math.max(0, Math.round(parsed.confidence))) : null,
      identifiedAs: String(parsed.identifiedAs || '').trim(),
      reason: String(parsed.reason || '').trim(),
      matches: !!parsed.matches
    };
  } catch (err) {
    clearTimeout(timeout);
    console.error('[DocumentPipeline] AI classification error:', err.message);
    return { confidence: null, identifiedAs: '', reason: 'AI classification failed: ' + err.message };
  }
}

async function uploadDocumentToDrive(userId, docRow, fileBuffer, mimeType) {
  if (!isGoogleDriveConfigured() || !fileBuffer) return '';
  try {
    var caseRes = await supabaseDbRequest('registration_cases', 'select=id,google_drive_folder_id&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
    var gpCase = caseRes.ok && Array.isArray(caseRes.data) && caseRes.data[0] ? caseRes.data[0] : null;
    if (!gpCase) return '';

    var folderId = await ensureGPDriveFolder(gpCase.id, null, null);
    if (!folderId) return '';

    var oldDriveFileId = docRow.google_drive_file_id || '';
    if (oldDriveFileId) {
      await deleteGoogleDriveFile(oldDriveFileId);
    }

    var fileName = docRow.file_name || docRow.document_key || 'document';
    var driveFile = await uploadToGoogleDrive(folderId, fileName, fileBuffer, mimeType || 'application/pdf');
    return driveFile && driveFile.id ? driveFile.id : '';
  } catch (err) {
    console.error('[DocumentPipeline] Drive upload error:', err.message);
    return '';
  }
}

async function createDocReviewTask(userId, documentKey, expectedLabel, confidence, aiResult, reviewStage) {
  var caseRes = await supabaseDbRequest('registration_cases', 'select=id&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
  var gpCase = caseRes.ok && Array.isArray(caseRes.data) && caseRes.data[0] ? caseRes.data[0] : null;
  if (!gpCase) return null;

  var canonKey = canonicalQualKey(documentKey);
  var existingRes = await supabaseDbRequest('registration_tasks',
    'select=id,status&case_id=eq.' + encodeURIComponent(gpCase.id) +
    '&task_type=eq.doc_review&related_document_key=eq.' + encodeURIComponent(canonKey) +
    '&status=in.(open,in_progress,waiting)&limit=1');
  var existing = existingRes.ok && Array.isArray(existingRes.data) && existingRes.data[0] ? existingRes.data[0] : null;

  if (existing) {
    await supabaseDbRequest('registration_tasks', 'id=eq.' + encodeURIComponent(existing.id), {
      method: 'PATCH',
      body: {
        status: 'open',
        ai_match_confidence: confidence,
        ai_match_reasoning: aiResult.reason || '',
        updated_at: new Date().toISOString()
      }
    });
    await supabaseDbRequest('task_timeline', '', {
      method: 'POST',
      body: [{ task_id: existing.id, case_id: gpCase.id, event_type: 'system', title: 'Document re-uploaded, task reopened', detail: 'AI confidence: ' + (confidence != null ? confidence + '%' : 'N/A') + '. Identified as: ' + (aiResult.identifiedAs || 'unknown'), actor: 'system' }]
    });
    return existing;
  }

  var profileRes = await supabaseDbRequest('user_profiles', 'select=first_name,last_name&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
  var profile = profileRes.ok && Array.isArray(profileRes.data) && profileRes.data[0] ? profileRes.data[0] : {};
  var gpName = [profile.first_name || '', profile.last_name || ''].join(' ').trim() || 'GP';

  return _createRegTask(gpCase.id, {
    task_type: 'doc_review',
    title: 'Review uploaded ' + (expectedLabel || documentKey) + ' for Dr ' + gpName,
    priority: 'normal',
    status: 'open',
    source_trigger: 'doc_upload',
    related_stage: reviewStage || inferStageFromDocKey(documentKey),
    related_document_key: canonKey,
    ai_match_confidence: confidence,
    ai_match_reasoning: aiResult.reason || '',
    _actor: 'system'
  });
}

// Create (or reopen) a normal-priority manual-review task for a flagged qualification doc.
async function createFlaggedDocTask(userId, documentKey, label, reason, reviewStage) {
  var caseRes = await supabaseDbRequest('registration_cases', 'select=id&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
  var gpCase = caseRes.ok && Array.isArray(caseRes.data) && caseRes.data[0] ? caseRes.data[0] : null;
  if (!gpCase) return null;

  var canonKey = canonicalQualKey(documentKey);

  // A flag supersedes any generic "Review uploaded …" doc_review task for the same
  // document — close it so the RSO sees a single, reasoned flag task, not both (the
  // doc_review may have been pre-created synchronously at upload time by
  // ensureDocReviewOnUpload).
  var supersedeRes = await supabaseDbRequest('registration_tasks',
    'select=id&case_id=eq.' + encodeURIComponent(gpCase.id) +
    '&task_type=eq.doc_review&related_document_key=eq.' + encodeURIComponent(canonKey) +
    '&status=in.(open,in_progress,waiting)');
  if (supersedeRes.ok && Array.isArray(supersedeRes.data)) {
    for (var sup = 0; sup < supersedeRes.data.length; sup++) {
      await _completeRegTask(supersedeRes.data[sup].id, gpCase.id, 'ai_auto');
    }
  }

  var existingRes = await supabaseDbRequest('registration_tasks',
    'select=id,status&case_id=eq.' + encodeURIComponent(gpCase.id) +
    '&task_type=eq.flagged_doc&related_document_key=eq.' + encodeURIComponent(canonKey) +
    '&status=in.(open,in_progress,waiting)&limit=1');
  var existing = existingRes.ok && Array.isArray(existingRes.data) && existingRes.data[0] ? existingRes.data[0] : null;

  if (existing) {
    await supabaseDbRequest('registration_tasks', 'id=eq.' + encodeURIComponent(existing.id), {
      method: 'PATCH',
      body: { status: 'open', description: reason, updated_at: new Date().toISOString() }
    });
    await supabaseDbRequest('task_timeline', '', {
      method: 'POST',
      body: [{ task_id: existing.id, case_id: gpCase.id, event_type: 'system', title: 'Document re-uploaded, flag reopened', detail: reason, actor: 'system' }]
    });
    return existing;
  }

  return _createRegTask(gpCase.id, {
    task_type: 'flagged_doc',
    title: 'Review flagged qualification: ' + (label || documentKey),
    description: reason,
    priority: 'normal',
    source_trigger: 'prepared_doc_scan',
    // Flagged qualifications default to the onboarding review stage (the onboarding
    // completion flow relies on this), but the document pipeline passes an explicit
    // reviewStage so a cert uploaded on the "prepare my documents" page is filed
    // under its own stage (AHPRA) rather than onboarding.
    related_stage: reviewStage || 'onboarding',
    related_document_key: canonKey,
    _actor: 'system'
  });
}

async function autoCloseDocReviewTask(userId, documentKey) {
  var caseRes = await supabaseDbRequest('registration_cases', 'select=id&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
  var gpCase = caseRes.ok && Array.isArray(caseRes.data) && caseRes.data[0] ? caseRes.data[0] : null;
  if (!gpCase) return;

  // Match the canonical key tasks were created with, and close BOTH the doc_review
  // and any open flagged_doc for this document — e.g. a previously-flagged
  // qualification that now passes verification on re-upload.
  var canonKey = canonicalQualKey(documentKey);
  var taskRes = await supabaseDbRequest('registration_tasks',
    'select=id&case_id=eq.' + encodeURIComponent(gpCase.id) +
    '&task_type=in.(doc_review,flagged_doc)&related_document_key=eq.' + encodeURIComponent(canonKey) +
    '&status=in.(open,in_progress,waiting)');
  if (taskRes.ok && Array.isArray(taskRes.data)) {
    for (var i = 0; i < taskRes.data.length; i++) {
      await _completeRegTask(taskRes.data[i].id, gpCase.id, 'ai_auto');
    }
  }
}

// Reliably ensure an RSO review task exists for a document the GP just uploaded.
// This runs SYNCHRONOUSLY (awaited inside the upload request) instead of relying on
// the best-effort, fire-and-forget AI pipeline (processDocumentUpload) — which is
// not guaranteed to run to completion on serverless and can silently bail (failed
// storage download, AI/classification error), leaving an uploaded document with no
// review task and no RSO visibility. With this, the RSO always sees uploaded docs;
// the AI pipeline, when it succeeds, still auto-approves (closing this task via
// autoCloseDocReviewTask) or reopens it idempotently.
// Idempotent: skips if the document is already resolved (approved/rejected) or if an
// open doc_review/flagged_doc task already covers it.
async function ensureDocReviewOnUpload(userId, documentKey, expectedLabel, reviewStage) {
  if (!isSupabaseDbConfigured() || !userId || !documentKey) return;
  try {
    var caseRes = await supabaseDbRequest('registration_cases', 'select=id&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
    var gpCase = caseRes.ok && Array.isArray(caseRes.data) && caseRes.data[0] ? caseRes.data[0] : null;
    if (!gpCase) return;

    // Latest stored row for this document. country_code is intentionally NOT filtered
    // here so casing variants (e.g. "AU" vs "au") still resolve.
    var docRes = await supabaseDbRequest('user_documents',
      'select=id,status&user_id=eq.' + encodeURIComponent(userId) +
      '&document_key=eq.' + encodeURIComponent(documentKey) +
      '&order=updated_at.desc&limit=1');
    var doc = docRes.ok && Array.isArray(docRes.data) && docRes.data[0] ? docRes.data[0] : null;
    if (!doc) return;
    if (doc.status === 'approved' || doc.status === 'rejected') return; // already resolved

    // Don't create a duplicate when an open review/flag task already covers this doc.
    var canonKey = canonicalQualKey(documentKey);
    var openRes = await supabaseDbRequest('registration_tasks',
      'select=id&case_id=eq.' + encodeURIComponent(gpCase.id) +
      '&task_type=in.(doc_review,flagged_doc)&related_document_key=eq.' + encodeURIComponent(canonKey) +
      '&status=in.(open,in_progress,waiting)&limit=1');
    var hasOpen = openRes.ok && Array.isArray(openRes.data) && openRes.data.length > 0;

    if (!hasOpen) {
      await createDocReviewTask(userId, documentKey, expectedLabel, null, {
        reason: 'Uploaded document awaiting RSO verification.', identifiedAs: ''
      }, reviewStage);
    }

    if (doc.status !== 'under_review') {
      await supabaseDbRequest('user_documents', 'id=eq.' + encodeURIComponent(doc.id), {
        method: 'PATCH', body: { status: 'under_review', updated_at: new Date().toISOString() }
      });
    }
  } catch (err) {
    console.error('[DocReview] ensureDocReviewOnUpload error:', err.message);
  }
}

async function processDocumentUpload(userId, documentKey, expectedLabel, countryCode, mimeType, reviewStage) {
  if (!isSupabaseDbConfigured() || !userId || !documentKey) return;

  try {
    var docQuery = 'select=*&user_id=eq.' + encodeURIComponent(userId) +
      '&document_key=eq.' + encodeURIComponent(documentKey) +
      (countryCode ? '&country_code=eq.' + encodeURIComponent(countryCode) : '') +
      '&order=updated_at.desc&limit=1';
    var docRes = await supabaseDbRequest('user_documents', docQuery);
    if (!docRes.ok || !Array.isArray(docRes.data) || docRes.data.length === 0) return;
    var doc = docRes.data[0];

    var storagePath = doc.storage_path || doc.file_url || '';
    if (!storagePath) return;
    var fileBuffer = await supabaseStorageDownloadObject(SUPABASE_DOCUMENT_BUCKET, storagePath);
    if (!fileBuffer) return;

    if (QUALIFICATION_DOC_KEYS.has(documentKey)) {
      var profRes = await supabaseDbRequest('user_profiles', 'select=first_name,last_name&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
      var prof = profRes.ok && Array.isArray(profRes.data) && profRes.data[0] ? profRes.data[0] : null;
      var profileName = prof ? [prof.first_name, prof.last_name].filter(Boolean).join(' ').trim() : '';
      var docTypeLabel = getDocumentLabelForKey(documentKey) || documentKey;
      var qualBlock = buildQualContentBlock(fileBuffer, mimeType || doc.mime_type);
      var vres = await verifyQualificationDocument({
        contentBlock: qualBlock,
        documentType: docTypeLabel,
        expectedCountry: String(countryCode || '').toUpperCase(),
        profileName: profileName,
        verifiedNames: [],
        requireCertification: isCertificationRequiredDocKey(documentKey)
      }).catch(function () { return { ok: false }; });

      if (vres && vres.ok && vres.verification) {
        var v = vres.verification;
        var outcome = classifyQualificationOutcome({ nameMatch: v.nameMatch, verified: v.verified });
        if (outcome.action === 'flag') {
          var reason = buildFlagReason(outcome.reasonKind, { nameFound: v.nameFound, profileName: profileName, expectedLabel: docTypeLabel, issues: v.issues });
          await supabaseDbRequest('user_documents', 'id=eq.' + encodeURIComponent(doc.id), {
            method: 'PATCH',
            body: { status: 'under_review', flag_reason: outcome.reasonKind, rejection_reason: reason, updated_at: new Date().toISOString() }
          });
          await createFlaggedDocTask(userId, documentKey, docTypeLabel, reason, reviewStage);
          await pushDocumentNotificationToUser(userId, { type: 'action', title: docTypeLabel + ' needs review', detail: reason });
          return; // handled — skip the generic type-only pipeline
        }
        // approve path: clear any stale flag.
        await supabaseDbRequest('user_documents', 'id=eq.' + encodeURIComponent(doc.id), {
          method: 'PATCH', body: { flag_reason: '', updated_at: new Date().toISOString() }
        });
        // Onboarding qualifications are collected only to name-match the GP and to
        // store the file for them to download later (at the MyIntealth step). A doc
        // that PASSED AI verification needs NO manual RSO review task — only flagged
        // ones do. Close any prior flag and stop before the generic pipeline would
        // create a "Review uploaded …" doc_review task. (Non-onboarding prepared-doc
        // uploads fall through to the existing doc_review pipeline so the RSO still
        // reviews those.)
        if (documentKey === 'onboarding_primary_med_degree' || documentKey === 'onboarding_specialist_qualification') {
          await autoCloseDocReviewTask(userId, documentKey);
          return;
        }
      }
      // if vres not ok (AI error), fall through to the existing generic pipeline
    }

    var aiResult = await classifyDocumentWithAI(fileBuffer, mimeType || doc.mime_type, documentKey, expectedLabel);
    var confidence = aiResult.confidence;
    var action = classifyConfidenceAction(confidence);

    await supabaseDbRequest('user_documents', 'id=eq.' + encodeURIComponent(doc.id), {
      method: 'PATCH',
      body: {
        ai_classification_confidence: confidence,
        ai_classification_result: aiResult.identifiedAs || '',
        updated_at: new Date().toISOString()
      }
    });

    if (action === 'auto_approve') {
      var driveFileId = await uploadDocumentToDrive(userId, doc, fileBuffer, mimeType || doc.mime_type);
      await supabaseDbRequest('user_documents', 'id=eq.' + encodeURIComponent(doc.id), {
        method: 'PATCH',
        body: {
          status: 'approved',
          reviewed_by: 'ai_auto',
          reviewed_at: new Date().toISOString(),
          google_drive_file_id: driveFileId || '',
          rejection_reason: '',
          updated_at: new Date().toISOString()
        }
      });
      await autoCloseDocReviewTask(userId, documentKey);

    } else if (action === 'va_review') {
      await supabaseDbRequest('user_documents', 'id=eq.' + encodeURIComponent(doc.id), {
        method: 'PATCH',
        body: { status: 'under_review', rejection_reason: '', updated_at: new Date().toISOString() }
      });
      await createDocReviewTask(userId, documentKey, expectedLabel, confidence, aiResult, reviewStage);
      await pushDocumentNotificationToUser(userId, {
        type: 'info',
        title: (expectedLabel || documentKey) + ' under review',
        detail: 'We\'re reviewing your document. This usually takes less than 24 hours.'
      });

    } else {
      var reason = buildRejectionMessage(aiResult.identifiedAs, expectedLabel || documentKey);
      await supabaseDbRequest('user_documents', 'id=eq.' + encodeURIComponent(doc.id), {
        method: 'PATCH',
        body: { status: 'rejected', rejection_reason: reason, updated_at: new Date().toISOString() }
      });
      // The document is bounced back to the GP — close any open review task (it may
      // have been pre-created synchronously at upload time by ensureDocReviewOnUpload)
      // so the RSO queue doesn't show a "review" task for a now-rejected document.
      await autoCloseDocReviewTask(userId, documentKey);
      await pushDocumentNotificationToUser(userId, {
        type: 'action',
        title: (expectedLabel || documentKey) + ' needs attention',
        detail: reason
      });
    }
  } catch (err) {
    console.error('[DocumentPipeline] processDocumentUpload error:', err.message);
  }
}

function mapSupabaseProfileRowToApiProfile(row, email) {
  const phone = row.phone || [row.country_dial || '', row.phone_number || ''].filter(Boolean).join(' ').trim();
  return {
    firstName: row.first_name || '',
    lastName: row.last_name || '',
    email: row.email || email,
    phone,
    registrationNumber: row.registration_number || '',
    gmcNumber: row.gmc_number || '',
    specialistCountry: row.registration_country || '',
    hasPassword: true,
    profilePhotoName: row.profile_photo_name || '',
    profilePhotoDataUrl: row.profile_photo_data_url || '',
    idCopyName: row.id_copy_name || '',
    idCopyDataUrl: row.id_copy_data_url || '',
    cvFileName: row.cv_file_name || '',
    updatedAt: row.updated_at || null
  };
}

function splitPhoneForProfile(phoneValue) {
  const value = String(phoneValue || '').trim();
  if (!value) return { countryDial: '', phoneNumber: '' };
  const match = value.match(/^(\+\d{1,4})\s*(.*)$/);
  if (!match) return { countryDial: '', phoneNumber: value };
  return {
    countryDial: match[1] || '',
    phoneNumber: String(match[2] || '').trim()
  };
}

async function getSupabaseUserProfile(email, sessionUserId = null) {
  const normalizedEmail = String(email || '').trim().toLowerCase();
  if (!normalizedEmail) return null;

  const byEmail = await supabaseDbRequest(
    'user_profiles',
    `select=*&email=eq.${encodeURIComponent(normalizedEmail)}&limit=1`
  );
  if (byEmail.ok && Array.isArray(byEmail.data) && byEmail.data.length > 0) {
    return byEmail.data[0];
  }

  if (!sessionUserId) return null;
  const byId = await supabaseDbRequest(
    'user_profiles',
    `select=*&user_id=eq.${encodeURIComponent(sessionUserId)}&limit=1`
  );
  if (!byId.ok || !Array.isArray(byId.data) || byId.data.length === 0) return null;
  return byId.data[0];
}

function filterUserStateForClient(source) {
  const filtered = {};
  const state = source && typeof source === 'object' ? source : {};
  for (const key of USER_STATE_KEYS) {
    if (Object.prototype.hasOwnProperty.call(state, key)) {
      filtered[key] = state[key];
    }
  }
  var stageRaw = filtered.gp_admin_stage_override;
  try {
    if (typeof stageRaw === 'string') stageRaw = JSON.parse(stageRaw);
  } catch (e) {}
  var stageIdx = ['placement', 'myintealth', 'amc', 'career', 'ahpra', 'visa', 'pbs', 'commencement']
    .indexOf(String(stageRaw || ''));
  var overrideAt = Date.parse(filtered.gp_stage_override_at || '') || 0;
  var idUpdatedAt = Date.parse(filtered.gp_amc_myintealth_id_updated_at || '') || 0;
  if (filtered.gp_amc_myintealth_id && overrideAt && stageIdx >= 0 && stageIdx <= 2 && idUpdatedAt <= overrideAt) {
    delete filtered.gp_amc_myintealth_id;
    delete filtered.gp_amc_myintealth_id_updated_at;
  }
  return filtered;
}

function buildFallbackApiProfile(email, sessionProfile = null) {
  const normalizedEmail = String(email || '').trim().toLowerCase();
  const stored = dbState.userProfiles[normalizedEmail] || {};
  const user = dbState.users[normalizedEmail] || {};
  const sessionData = sessionProfile && typeof sessionProfile === 'object' ? sessionProfile : {};
  const phone = stored.phone || [
    sessionData.countryDial || user.countryDial || '',
    sessionData.phoneNumber || user.phoneNumber || ''
  ].filter(Boolean).join(' ').trim();

  return {
    firstName: stored.firstName || user.firstName || sessionData.firstName || '',
    lastName: stored.lastName || user.lastName || sessionData.lastName || '',
    email: stored.email || user.email || sessionData.email || normalizedEmail,
    phone,
    registrationNumber: stored.registrationNumber || '',
    gmcNumber: stored.gmcNumber || '',
    specialistCountry: user.registrationCountry || stored.specialistCountry || sessionData.registrationCountry || '',
    hasPassword: true,
    profilePhotoName: stored.profilePhotoName || '',
    profilePhotoDataUrl: stored.profilePhotoDataUrl || '',
    idCopyName: stored.idCopyName || '',
    idCopyDataUrl: stored.idCopyDataUrl || '',
    cvFileName: stored.cvFileName || '',
    updatedAt: stored.updatedAt || null
  };
}

function buildBootstrapProfilePayload(profile) {
  const source = profile && typeof profile === 'object' ? profile : {};
  return {
    ...source,
    profilePhotoDataUrl: '',
    idCopyDataUrl: ''
  };
}

async function buildAuthBootstrapForEmail(email, options = {}) {
  const normalizedEmail = String(email || '').trim().toLowerCase();
  const sessionUserId = String(options.sessionUserId || '').trim() || null;
  const sessionProfile = options.sessionProfile && typeof options.sessionProfile === 'object'
    ? options.sessionProfile
    : null;

  if (!normalizedEmail) {
    return {
      sessionProfile,
      state: {},
      stateUpdatedAt: null,
      profile: buildBootstrapProfilePayload(buildFallbackApiProfile('', sessionProfile)),
      accountStatus: 'active',
      cachedAt: new Date().toISOString()
    };
  }

  let profile = buildFallbackApiProfile(normalizedEmail, sessionProfile);
  let filteredState = {};
  let stateUpdatedAt = null;
  let accountStatus = 'active';

  if (isSupabaseDbConfigured()) {
    const [remoteState, remoteProfile] = await Promise.all([
      getSupabaseUserStateByEmail(normalizedEmail),
      getSupabaseUserProfile(normalizedEmail, sessionUserId)
    ]);
    if (remoteState && remoteState.state && typeof remoteState.state === 'object') {
      filteredState = filterUserStateForClient(remoteState.state);
      stateUpdatedAt = remoteState.updatedAt || null;
      if (typeof remoteState.state.account_status === 'string' && remoteState.state.account_status.trim()) {
        accountStatus = remoteState.state.account_status.trim();
      }
    }
    if (remoteProfile) {
      profile = mapSupabaseProfileRowToApiProfile(remoteProfile, normalizedEmail);
    }
  } else {
    const localState = dbState.userState[normalizedEmail] && typeof dbState.userState[normalizedEmail] === 'object'
      ? dbState.userState[normalizedEmail]
      : {};
    filteredState = filterUserStateForClient(localState);
    stateUpdatedAt = typeof localState.updatedAt === 'string' ? localState.updatedAt : null;
    if (typeof localState.account_status === 'string' && localState.account_status.trim()) {
      accountStatus = localState.account_status.trim();
    }
  }

  return {
    sessionProfile,
    state: filteredState,
    stateUpdatedAt,
    profile: buildBootstrapProfilePayload(profile),
    accountStatus,
    cachedAt: new Date().toISOString()
  };
}

function getWarmAuthBootstrap(email) {
  const normalizedEmail = String(email || '').trim().toLowerCase();
  if (!normalizedEmail) return null;
  const cached = _authBootstrapWarmCache.get(normalizedEmail);
  if (!cached) return null;
  if (Number(cached.expiresAt || 0) <= Date.now()) {
    _authBootstrapWarmCache.delete(normalizedEmail);
    return null;
  }
  return cached.value && typeof cached.value === 'object' ? cached.value : null;
}

function setWarmAuthBootstrap(email, bootstrap) {
  const normalizedEmail = String(email || '').trim().toLowerCase();
  if (!normalizedEmail || !bootstrap || typeof bootstrap !== 'object') return;
  _authBootstrapWarmCache.set(normalizedEmail, {
    expiresAt: Date.now() + AUTH_BOOTSTRAP_CACHE_TTL_MS,
    value: bootstrap
  });
}

function queueAuthBootstrapWarm(email, options = {}) {
  const normalizedEmail = String(email || '').trim().toLowerCase();
  if (!normalizedEmail || !isValidEmail(normalizedEmail)) return Promise.resolve(null);

  const cached = getWarmAuthBootstrap(normalizedEmail);
  if (cached) {
    return Promise.resolve({
      ...cached,
      sessionProfile: options.sessionProfile || cached.sessionProfile || null
    });
  }

  if (_authBootstrapInFlight.has(normalizedEmail)) {
    return _authBootstrapInFlight.get(normalizedEmail);
  }

  const inFlight = buildAuthBootstrapForEmail(normalizedEmail, options)
    .then((bootstrap) => {
      if (bootstrap) setWarmAuthBootstrap(normalizedEmail, bootstrap);
      return bootstrap;
    })
    .catch(() => null)
    .finally(() => {
      _authBootstrapInFlight.delete(normalizedEmail);
    });

  _authBootstrapInFlight.set(normalizedEmail, inFlight);
  return inFlight;
}

async function resolveAuthBootstrap(email, options = {}) {
  const normalizedEmail = String(email || '').trim().toLowerCase();
  const sessionProfile = options.sessionProfile && typeof options.sessionProfile === 'object'
    ? options.sessionProfile
    : null;

  const cached = getWarmAuthBootstrap(normalizedEmail);
  if (cached) {
    const merged = { ...cached, sessionProfile: sessionProfile || cached.sessionProfile || null };
    setWarmAuthBootstrap(normalizedEmail, merged);
    return merged;
  }

  const warmed = await queueAuthBootstrapWarm(normalizedEmail, options);
  if (warmed) {
    const merged = { ...warmed, sessionProfile: sessionProfile || warmed.sessionProfile || null };
    setWarmAuthBootstrap(normalizedEmail, merged);
    return merged;
  }

  return buildAuthBootstrapForEmail(normalizedEmail, options);
}

function resolveFastAuthBootstrap(email, options = {}) {
  const normalizedEmail = String(email || '').trim().toLowerCase();
  const sessionProfile = options.sessionProfile && typeof options.sessionProfile === 'object'
    ? options.sessionProfile
    : null;

  if (!normalizedEmail) {
    return { bootstrap: null, bootstrapPending: false };
  }

  const cached = getWarmAuthBootstrap(normalizedEmail);
  if (cached) {
    const merged = { ...cached, sessionProfile: sessionProfile || cached.sessionProfile || null };
    setWarmAuthBootstrap(normalizedEmail, merged);
    return { bootstrap: merged, bootstrapPending: false };
  }

  queueAuthBootstrapWarm(normalizedEmail, options).catch(() => {});
  return { bootstrap: null, bootstrapPending: true };
}

async function upsertSupabaseUserProfile(userId, email, clean, existingRow = null) {
  if (!userId) return null;
  const current = existingRow && typeof existingRow === 'object' ? existingRow : {};
  const split = splitPhoneForProfile(clean.phone);
  const countryDial = split.countryDial || current.country_dial || '';
  const phoneNumber = split.phoneNumber || current.phone_number || '';
  const phone = clean.phone || [countryDial, phoneNumber].filter(Boolean).join(' ').trim();

  const payload = {
    user_id: userId,
    email,
    first_name: clean.firstName || current.first_name || '',
    last_name: clean.lastName || current.last_name || '',
    country_dial: countryDial,
    phone_number: phoneNumber,
    registration_country: clean.specialistCountry || current.registration_country || '',
    phone,
    registration_number: clean.registrationNumber || current.registration_number || '',
    gmc_number: clean.gmcNumber || current.gmc_number || '',
    profile_photo_name: clean.profilePhotoName || current.profile_photo_name || '',
    profile_photo_data_url: clean.profilePhotoDataUrl || current.profile_photo_data_url || '',
    id_copy_name: clean.idCopyName || current.id_copy_name || '',
    id_copy_data_url: clean.idCopyDataUrl || current.id_copy_data_url || '',
    cv_file_name: clean.cvFileName || current.cv_file_name || '',
    updated_at: new Date().toISOString()
  };

  const write = await supabaseDbRequest(
    'user_profiles',
    'on_conflict=user_id',
    {
      method: 'POST',
      headers: { Prefer: 'resolution=merge-duplicates,return=representation' },
      body: [payload]
    }
  );
  if (!write.ok || !Array.isArray(write.data) || write.data.length === 0) return null;
  return write.data[0];
}

async function supabaseAuthRequest(endpoint, payload) {
  if (!isSupabaseConfigured()) {
    return { ok: false, status: 503, data: { message: 'Supabase is not configured.' } };
  }

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 10000);
  try {
    const response = await fetch(`${SUPABASE_URL}/auth/v1/${endpoint}`, {
      method: 'POST',
      signal: controller.signal,
      headers: {
        apikey: SUPABASE_PUBLISHABLE_KEY,
        Authorization: `Bearer ${SUPABASE_PUBLISHABLE_KEY}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(payload || {})
    });
    const data = await response.json().catch(() => ({}));
    return { ok: response.ok, status: response.status, data };
  } catch (err) {
    return { ok: false, status: 502, data: { message: 'Failed to reach Supabase auth service.' } };
  } finally {
    clearTimeout(timeout);
  }
}

async function supabaseAuthAdminRequest(pathname, options = {}) {
  if (!isSupabaseDbConfigured()) {
    return { ok: false, status: 503, data: { message: 'Supabase admin auth is not configured.' } };
  }

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 10000);
  try {
    const response = await fetch(`${SUPABASE_URL}/auth/v1/${pathname}`, {
      method: options.method || 'GET',
      signal: controller.signal,
      headers: {
        apikey: SUPABASE_SERVICE_ROLE_KEY,
        Authorization: `Bearer ${SUPABASE_SERVICE_ROLE_KEY}`,
        ...(options.body !== undefined ? { 'Content-Type': 'application/json' } : {}),
        ...((options && options.headers) || {})
      },
      body: options.body !== undefined ? JSON.stringify(options.body) : undefined
    });
    const data = await response.json().catch(() => ({}));
    return { ok: response.ok, status: response.status, data };
  } catch (err) {
    return { ok: false, status: 502, data: { message: 'Failed to reach Supabase admin auth service.' } };
  } finally {
    clearTimeout(timeout);
  }
}

function getSessionProfileFromUser(email) {
  const key = String(email || '').trim().toLowerCase();
  const user = dbState.users[key] || {};
  const profile = dbState.userProfiles[key] || {};

  return {
    firstName: user.firstName || profile.firstName || '',
    lastName: user.lastName || profile.lastName || '',
    email: key,
    supabaseUserId: user.supabaseUserId || '',
    countryDial: user.countryDial || '',
    phoneNumber: user.phoneNumber || '',
    registrationCountry: user.registrationCountry || profile.specialistCountry || ''
  };
}

function getSessionProfileFromSupabaseUser(supaUser, fallbackEmail = '') {
  const email = String(
    (supaUser && typeof supaUser.email === 'string' && supaUser.email) || fallbackEmail || ''
  ).trim().toLowerCase();
  const metadata = supaUser && supaUser.user_metadata && typeof supaUser.user_metadata === 'object'
    ? supaUser.user_metadata
    : {};
  return {
    firstName: String(metadata.firstName || metadata.given_name || '').trim(),
    lastName: String(metadata.lastName || metadata.family_name || '').trim(),
    email,
    supabaseUserId: String((supaUser && supaUser.id) || '').trim(),
    countryDial: String(metadata.countryDial || '').trim(),
    phoneNumber: String(metadata.phoneNumber || '').trim(),
    registrationCountry: String(metadata.registrationCountry || '').trim()
  };
}

// Ensure a user_profiles row exists in Supabase for a newly authenticated user.
// Called after signup/login to guarantee that state, profile, and onboarding
// endpoints can resolve the user ID.
async function ensureSupabaseUserProfile(supaUser) {
  if (!isSupabaseDbConfigured()) return;
  const supabaseUserId = String(supaUser && supaUser.id ? supaUser.id : '').trim();
  const email = String(supaUser && supaUser.email ? supaUser.email : '').trim().toLowerCase();
  if (!supabaseUserId || !email) return;

  const meta = supaUser && typeof supaUser.user_metadata === 'object' && supaUser.user_metadata
    ? supaUser.user_metadata
    : {};
  const firstName = String(meta.firstName || meta.given_name || '').trim();
  const lastName = String(meta.lastName || meta.family_name || '').trim();

  // Check if row already exists (may be created by DB trigger with empty names)
  const existing = await supabaseDbRequest(
    'user_profiles',
    `select=user_id,first_name,last_name,phone_number,phone&user_id=eq.${encodeURIComponent(supabaseUserId)}&limit=1`
  );
  if (existing.ok && Array.isArray(existing.data) && existing.data.length > 0) {
    // Row exists — update name if signup provided one and profile is still blank
    var existingRow = existing.data[0];
    const countryDial = String(meta.countryDial || '').trim();
    const phoneNumber = String(meta.phoneNumber || '').trim();
    const phone = [countryDial, phoneNumber].filter(Boolean).join(' ').trim();
    const needsName = (firstName || lastName) && !existingRow.first_name && !existingRow.last_name;
    const needsPhone = phone && !existingRow.phone_number && !existingRow.phone;
    if (needsName || needsPhone) {
      var patch = { updated_at: new Date().toISOString() };
      if (firstName) patch.first_name = firstName;
      if (lastName) patch.last_name = lastName;
      if (needsPhone) {
        patch.country_dial = countryDial;
        patch.phone_number = phoneNumber;
        patch.phone = phone;
      }
      await supabaseDbRequest('user_profiles', 'user_id=eq.' + encodeURIComponent(supabaseUserId), {
        method: 'PATCH',
        headers: { Prefer: 'return=minimal' },
        body: patch
      });
    }
    return;
  }

  const payload = {
    user_id: supabaseUserId,
    email,
    first_name: firstName,
    last_name: lastName,
    country_dial: String(meta.countryDial || '').trim(),
    phone_number: String(meta.phoneNumber || '').trim(),
    phone: [String(meta.countryDial || '').trim(), String(meta.phoneNumber || '').trim()].filter(Boolean).join(' ').trim(),
    registration_country: String(meta.registrationCountry || '').trim(),
    updated_at: new Date().toISOString()
  };

  await supabaseDbRequest('user_profiles', 'on_conflict=user_id', {
    method: 'POST',
    headers: { Prefer: 'resolution=merge-duplicates,return=minimal' },
    body: [payload]
  });
}

function upsertLocalUserFromSupabaseUser(supaUser) {
  const email = String(supaUser && supaUser.email ? supaUser.email : '').trim().toLowerCase();
  if (!email) return null;
  if (isSupabaseDbConfigured()) return email;
  const supabaseUserId = String(supaUser && supaUser.id ? supaUser.id : '').trim();

  const meta = supaUser && typeof supaUser.user_metadata === 'object' && supaUser.user_metadata
    ? supaUser.user_metadata
    : {};
  const firstName = String(meta.firstName || meta.given_name || '').trim();
  const lastName = String(meta.lastName || meta.family_name || '').trim();
  const countryDial = String(meta.countryDial || '').trim();
  const phoneNumber = String(meta.phoneNumber || '').trim();
  const registrationCountry = String(meta.registrationCountry || '').trim();
  const updatedAt = new Date().toISOString();

  dbState.users[email] = {
    ...(dbState.users[email] || {}),
    email,
    supabaseUserId: supabaseUserId || (dbState.users[email] && dbState.users[email].supabaseUserId) || '',
    firstName: firstName || (dbState.users[email] && dbState.users[email].firstName) || '',
    lastName: lastName || (dbState.users[email] && dbState.users[email].lastName) || '',
    countryDial: countryDial || (dbState.users[email] && dbState.users[email].countryDial) || '',
    phoneNumber: phoneNumber || (dbState.users[email] && dbState.users[email].phoneNumber) || '',
    registrationCountry: registrationCountry || (dbState.users[email] && dbState.users[email].registrationCountry) || '',
    updatedAt
  };

  if (!dbState.userProfiles[email]) {
    dbState.userProfiles[email] = {
      firstName: dbState.users[email].firstName || '',
      lastName: dbState.users[email].lastName || '',
      email,
      phone: `${dbState.users[email].countryDial || ''} ${dbState.users[email].phoneNumber || ''}`.trim(),
      specialistCountry: dbState.users[email].registrationCountry || '',
      registrationNumber: '',
      gmcNumber: '',
      profilePhotoName: '',
      profilePhotoDataUrl: '',
      idCopyName: '',
      idCopyDataUrl: '',
      cvFileName: '',
      coverLetterFileName: '',
      updatedAt
    };
  }

  saveDbState();
  return email;
}

function getSessionSupabaseUserId(session) {
  const value = session && session.userProfile && typeof session.userProfile.supabaseUserId === 'string'
    ? session.userProfile.supabaseUserId.trim()
    : '';
  return value || null;
}

function cleanup() {
  const ts = now();
  let dirty = false;

  for (const [k, v] of Object.entries(dbState.otpChallenges)) {
    if (!v || v.expiresAt <= ts) {
      delete dbState.otpChallenges[k];
      dirty = true;
    }
  }

  for (const [k, v] of Object.entries(dbState.rateLimits)) {
    if (!v || v.windowStart + RATE_WINDOW_MS <= ts) {
      delete dbState.rateLimits[k];
      dirty = true;
    }
  }

  for (const [k, v] of Object.entries(dbState.sessions)) {
    if (!v || v.expiresAt <= ts) {
      delete dbState.sessions[k];
      dirty = true;
    }
  }

  const resetRetentionMs = 24 * 60 * 60 * 1000;
  for (const [k, v] of Object.entries(dbState.passwordResetTokens)) {
    if (!v || v.expiresAt <= ts || (v.used && (ts - (v.usedAt || ts)) > resetRetentionMs)) {
      delete dbState.passwordResetTokens[k];
      dirty = true;
    }
  }

  if (dirty) saveDbState();
}

/* ───────── Zoom Server-to-Server OAuth ───────── */

function isZoomConfigured() {
  return !!(process.env.ZOOM_CLIENT_ID && process.env.ZOOM_CLIENT_SECRET && process.env.ZOOM_ACCOUNT_ID);
}

let _zoomAccessToken = '';
let _zoomTokenExpiresAt = 0;

async function getZoomAccessToken() {
  if (_zoomAccessToken && Date.now() < _zoomTokenExpiresAt - 60000) {
    return _zoomAccessToken;
  }
  const clientId = process.env.ZOOM_CLIENT_ID;
  const clientSecret = process.env.ZOOM_CLIENT_SECRET;
  const accountId = process.env.ZOOM_ACCOUNT_ID;
  const credentials = Buffer.from(clientId + ':' + clientSecret).toString('base64');
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 15000);
  try {
    const res = await fetch('https://zoom.us/oauth/token', {
      method: 'POST',
      signal: controller.signal,
      headers: {
        'Authorization': 'Basic ' + credentials,
        'Content-Type': 'application/x-www-form-urlencoded'
      },
      body: 'grant_type=account_credentials&account_id=' + encodeURIComponent(accountId)
    });
    if (!res.ok) {
      const text = await res.text().catch(() => '');
      throw new Error('Zoom OAuth failed: ' + res.status + ' ' + text);
    }
    const data = await res.json();
    _zoomAccessToken = data.access_token || '';
    _zoomTokenExpiresAt = Date.now() + ((data.expires_in || 3600) * 1000);
    return _zoomAccessToken;
  } finally {
    clearTimeout(timeout);
  }
}

async function createZoomMeeting(options) {
  const token = await getZoomAccessToken();
  const body = {
    topic: options.topic || 'GP Link Interview',
    type: 2, // scheduled meeting
    start_time: options.startTime, // ISO 8601
    duration: options.duration || 30,
    timezone: options.timezone || 'Australia/Sydney',
    settings: {
      host_video: true,
      participant_video: true,
      join_before_host: false,
      waiting_room: true,
      auto_recording: 'none',
      meeting_authentication: false
    }
  };
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 15000);
  try {
    const res = await fetch('https://api.zoom.us/v2/users/me/meetings', {
      method: 'POST',
      signal: controller.signal,
      headers: {
        'Authorization': 'Bearer ' + token,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(body)
    });
    if (!res.ok) {
      const text = await res.text().catch(() => '');
      throw new Error('Zoom meeting creation failed: ' + res.status + ' ' + text);
    }
    return res.json();
  } finally {
    clearTimeout(timeout);
  }
}

async function deleteZoomMeeting(meetingId) {
  const token = await getZoomAccessToken();
  const delController = new AbortController();
  const delTimeout = setTimeout(() => delController.abort(), 15000);
  try {
    const res = await fetch('https://api.zoom.us/v2/meetings/' + encodeURIComponent(meetingId), {
      method: 'DELETE',
      signal: delController.signal,
      headers: { 'Authorization': 'Bearer ' + token }
    });
    return res.ok;
  } finally {
    clearTimeout(delTimeout);
  }
}

/* ───────── Interview integration helpers: Zoom create + Google Calendar ───────── */

var gcalLib = require('./lib/google-calendar.js');

// Mint a raw Google access token for the given scopes (reuses the same service-account
// credentials already used for Drive, adding the Calendar scope as needed).
async function getGoogleAccessToken(scopes, impersonateEmail) {
  const { google } = require('googleapis');
  const jwtOpts = {
    email: GOOGLE_SERVICE_ACCOUNT_EMAIL,
    key: GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY,
    scopes: scopes || []
  };
  if (impersonateEmail) jwtOpts.subject = impersonateEmail;
  const auth = new google.auth.JWT(jwtOpts);
  await auth.authorize();
  return auth.credentials.access_token;
}

function isGoogleCalendarConfigured() {
  return !!(GOOGLE_SERVICE_ACCOUNT_EMAIL && GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY && process.env.GOOGLE_CALENDAR_ID);
}

// Read busy intervals from Google Calendar (or from the local fakeCalendar store).
async function gcalReadBusy(o) {
  if (!isGoogleCalendarConfigured()) {
    return (dbState.fakeCalendar || []).filter(function (e) {
      return new Date(e.endUtc) > new Date(o.fromUtc) && new Date(e.startUtc) < new Date(o.toUtc);
    }).map(function (e) { return { startUtc: e.startUtc, endUtc: e.endUtc }; });
  }
  var token = await getGoogleAccessToken(['https://www.googleapis.com/auth/calendar'], process.env.GOOGLE_CALENDAR_IMPERSONATE_EMAIL || undefined);
  var req = gcalLib.buildFreeBusyRequest({ calendarId: process.env.GOOGLE_CALENDAR_ID, fromUtc: o.fromUtc, toUtc: o.toUtc });
  var res = await fetch(req.url, { method: 'POST', headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' }, body: JSON.stringify(req.body) });
  var json = await res.json();
  return gcalLib.parseFreeBusy(json, process.env.GOOGLE_CALENDAR_ID);
}

// Create a Calendar event (or push to the local fakeCalendar store).
async function gcalCreateEvent(o) {
  if (!isGoogleCalendarConfigured()) {
    var id = 'gcal_local_' + ((dbState.fakeCalendar ? dbState.fakeCalendar.length : 0) + 1);
    dbState.fakeCalendar = dbState.fakeCalendar || [];
    dbState.fakeCalendar.push({ id: id, startUtc: o.startUtc, endUtc: o.endUtc, summary: o.summary });
    saveDbState();
    return { id: id };
  }
  var token = await getGoogleAccessToken(['https://www.googleapis.com/auth/calendar'], process.env.GOOGLE_CALENDAR_IMPERSONATE_EMAIL || undefined);
  var req = gcalLib.buildEventInsert(Object.assign({ calendarId: process.env.GOOGLE_CALENDAR_ID }, o));
  var res = await fetch(req.url, { method: 'POST', headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' }, body: JSON.stringify(req.body) });
  var json = await res.json();
  return { id: json.id };
}

// Create a Zoom meeting for an interview (separate from the consultation Zoom path).
async function createZoomInterviewMeeting(o) {
  if (!isZoomConfigured()) {
    return { id: 'zoom_local_' + Date.now(), uuid: 'uuid_local', join_url: 'https://zoom.local/j/interview', passcode: '' };
  }
  var token = await getZoomAccessToken();
  var res = await fetch('https://api.zoom.us/v2/users/me/meetings', {
    method: 'POST',
    headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
    body: JSON.stringify({ topic: o.topic, type: 2, start_time: o.startUtc, duration: o.durationMin, timezone: 'UTC', settings: { join_before_host: false } })
  });
  var d = await res.json();
  return { id: String(d.id || ''), uuid: d.uuid || '', join_url: d.join_url || '', passcode: d.password || '' };
}

/* ───────── Email via Resend HTTP API ───────── */

function isEmailConfigured() {
  return !!(process.env.RESEND_API_KEY);
}

// ── Email suppression (Phase 6 C3, audit M2) ────────────────────────────────
// Hard bounces + spam complaints (fed by POST /api/webhooks/resend) land in
// public.email_suppression. ONLY sendEmail calls tagged category:'marketing'
// consult it — transactional mail (OTP, security, offers, task notices)
// always sends. Dual-mode: Supabase table in prod, dbState.emailSuppression
// map in local JSON dev.

function normalizeSuppressionEmail(email) {
  return String(email || '').trim().toLowerCase();
}

async function isEmailSuppressed(email) {
  const lower = normalizeSuppressionEmail(email);
  if (!lower) return false;
  try {
    if (isSupabaseDbConfigured()) {
      const r = await supabaseDbRequest('email_suppression', 'select=email&email=eq.' + encodeURIComponent(lower) + '&limit=1');
      // Missing table / transient errors → NOT suppressed (fail open: a lost
      // suppression check must never block mail wholesale).
      return !!(r && r.ok && Array.isArray(r.data) && r.data.length > 0);
    }
    return !!(dbState.emailSuppression && Object.prototype.hasOwnProperty.call(dbState.emailSuppression, lower));
  } catch (err) {
    console.error('[suppression] lookup failed (treating as not suppressed):', err && err.message);
    return false;
  }
}

async function suppressEmail(email, reason, source) {
  const lower = normalizeSuppressionEmail(email);
  if (!lower || !isValidEmail(lower)) return false;
  try {
    if (isSupabaseDbConfigured()) {
      const r = await supabaseDbRequest('email_suppression', 'on_conflict=email', {
        method: 'POST',
        headers: { Prefer: 'resolution=merge-duplicates,return=minimal' },
        body: [{ email: lower, reason: String(reason || '').slice(0, 120) || null, source: String(source || '').slice(0, 120) || null }]
      });
      if (!r || !r.ok) {
        console.error('[suppression] insert failed for', lower, '- status', r && r.status);
        return false;
      }
      return true;
    }
    if (lower === '__proto__' || lower === 'constructor' || lower === 'prototype') return false;
    if (!dbState.emailSuppression || typeof dbState.emailSuppression !== 'object') dbState.emailSuppression = {};
    dbState.emailSuppression[lower] = { reason: String(reason || ''), source: String(source || ''), created_at: new Date().toISOString() };
    saveDbState();
    return true;
  } catch (err) {
    console.error('[suppression] suppressEmail error:', err && err.message);
    return false;
  }
}

// Send-failure visibility (Phase 6 C3): every REAL Resend failure (API error /
// network — not "email not configured", not a suppression skip) is recorded in
// client_errors (source='server', route 'email-send') so the ~6 fire-and-forget
// sendEmail call sites stop dropping failures invisibly. Surfaces on the admin
// Technical tab. Never throws.
async function recordEmailFailure(to, subject, errorText) {
  try {
    const toLabel = Array.isArray(to) ? to.join(', ') : String(to || '');
    const err = new Error('Email send failed: ' + String(errorText || 'unknown error').slice(0, 300));
    await recordServerError(err, {
      route: 'email-send',
      method: 'EMAIL',
      label: 'to=' + toLabel.slice(0, 200) + ' · subject=' + String(subject || '').slice(0, 200)
    });
  } catch (_) { /* visibility must never break the send path */ }
}

// from: optional { email, name } to send on behalf of a specific person (e.g. the assigned RSO).
// replyTo: optional address (or array) replies should go to. Both default to the GP Link sender.
// attachments (optional): [{ filename, content (base64 string), contentType? }]
// — forwarded to Resend's native attachments field (used by the in-app
// submit-to-practice candidate introduction to carry the GP's CV).
// category (optional): 'transactional' (default) | 'marketing'. Only
// 'marketing' respects the email_suppression list — bounced/complained
// recipients are silently skipped (result: { ok:false, suppressed:true }).
async function sendEmail({ to, subject, html, text, from, replyTo, attachments, scheduledAt, headers, category }) {
  if (!isEmailConfigured()) return { ok: false, error: 'Email not configured' };
  let recipients = (Array.isArray(to) ? to : [to]).filter(Boolean);
  if (String(category || 'transactional') === 'marketing') {
    const kept = [];
    for (const rcpt of recipients) {
      if (await isEmailSuppressed(rcpt)) {
        console.log('[sendEmail] skipping suppressed marketing recipient:', normalizeSuppressionEmail(rcpt));
      } else {
        kept.push(rcpt);
      }
    }
    if (kept.length === 0) {
      return { ok: false, suppressed: true, skipped: true, error: 'Recipient is on the suppression list' };
    }
    recipients = kept;
  }
  const fromEmail = (from && from.email && String(from.email).trim()) || process.env.RESEND_FROM_EMAIL || 'notifications@mygplink.com.au';
  const fromName = (from && from.name && String(from.name).trim()) || process.env.RESEND_FROM_NAME || 'GP Link';
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 10000);
  try {
    const emailPayload = {
      from: fromName + ' <' + fromEmail + '>',
      to: recipients,
      subject: subject,
      html: html || '',
      text: text || ''
    };
    if (replyTo) emailPayload.reply_to = Array.isArray(replyTo) ? replyTo : [replyTo];
    if (Array.isArray(attachments) && attachments.length > 0) {
      const cleanAttachments = attachments
        .filter((a) => a && a.filename && a.content)
        .map((a) => {
          const att = { filename: String(a.filename), content: String(a.content) };
          if (a.contentType || a.mimeType) att.content_type = String(a.contentType || a.mimeType);
          return att;
        });
      if (cleanAttachments.length > 0) emailPayload.attachments = cleanAttachments;
    }
    // Resend-native delayed send (ISO 8601, up to ~30 days out) — used to stagger
    // per-task sequences without a queue table or cron on serverless.
    if (scheduledAt) emailPayload.scheduled_at = scheduledAt;
    // Optional per-message email headers (e.g. List-Unsubscribe for nudge emails).
    if (headers && typeof headers === 'object') emailPayload.headers = headers;
    const res = await fetch(RESEND_API_URL, {
      method: 'POST',
      signal: controller.signal,
      headers: {
        'Authorization': 'Bearer ' + process.env.RESEND_API_KEY,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(emailPayload)
    });
    const resBody = await res.text().catch(() => '');
    if (!res.ok) {
      console.error('[sendEmail] Resend API error:', res.status, resBody.slice(0, 300));
      await recordEmailFailure(recipients, subject, 'Resend API error: ' + res.status + ' ' + resBody.slice(0, 200));
      return { ok: false, error: 'Resend API error: ' + res.status + ' ' + resBody.slice(0, 200) };
    }
    console.log('[sendEmail] Resend accepted:', to, '| response:', resBody.slice(0, 200));
    return { ok: true };
  } catch (err) {
    await recordEmailFailure(recipients, subject, String(err && err.message || err));
    return { ok: false, error: String(err && err.message || err) };
  } finally {
    clearTimeout(timeout);
  }
}

// ── Resend bounce/complaint webhook (Phase 6 C3, audit M2) ──────────────────
// Resend signs webhooks with Svix: headers svix-id / svix-timestamp /
// svix-signature, where svix-signature holds space-separated "v1,<base64sig>"
// entries and the expected signature is
//   base64( HMAC-SHA256( base64decode(secret without 'whsec_'),
//                        `${svix-id}.${svix-timestamp}.${rawBody}` ) )
// with a 5-minute timestamp tolerance. RESEND_WEBHOOK_SECRET is the signing
// secret ("whsec_…") from the Resend dashboard's webhook settings.
let _resendWebhookOpenWarned = false;

function verifyResendWebhookSignature(headersObj, rawBody, secret) {
  try {
    const id = String((headersObj && headersObj['svix-id']) || '').trim();
    const ts = String((headersObj && headersObj['svix-timestamp']) || '').trim();
    const sigHeader = String((headersObj && headersObj['svix-signature']) || '').trim();
    if (!id || !ts || !sigHeader) return false;
    const tsNum = Number(ts);
    if (!Number.isFinite(tsNum) || Math.abs(Date.now() / 1000 - tsNum) > 300) return false;
    const key = Buffer.from(String(secret).replace(/^whsec_/, ''), 'base64');
    if (!key.length) return false;
    const expected = crypto.createHmac('sha256', key).update(id + '.' + ts + '.' + rawBody, 'utf8').digest('base64');
    return sigHeader.split(/\s+/).some(function (part) {
      // Each entry looks like "v1,<sig>" — compare only same-version sigs.
      const commaAt = part.indexOf(',');
      const candidate = commaAt >= 0 ? part.slice(commaAt + 1) : part;
      return !!candidate && timingSafeEqualStrings(candidate, expected);
    });
  } catch (_) {
    return false;
  }
}

async function handleResendWebhook(req, res) {
  let raw = '';
  try {
    raw = (await readRawBody(req, 1024 * 1024)).toString('utf8');
  } catch (e) {
    sendJson(res, 400, { ok: false, message: 'Invalid body.' });
    return;
  }
  const whSecret = String(process.env.RESEND_WEBHOOK_SECRET || '').trim();
  if (whSecret) {
    if (!verifyResendWebhookSignature(req.headers, raw, whSecret)) {
      console.warn('[Resend webhook] Rejected delivery with missing/invalid Svix signature');
      sendJson(res, 401, { ok: false, error: 'Invalid signature' });
      return;
    }
  } else if (!_resendWebhookOpenWarned) {
    // Same warn-and-process posture as the Gmail webhook: works before the
    // owner sets the secret, verifies as soon as it IS set.
    _resendWebhookOpenWarned = true;
    console.warn('[Resend webhook] WARNING: RESEND_WEBHOOK_SECRET is not set — accepting UNVERIFIED deliveries. Set it to the Svix signing secret (whsec_…) from the Resend webhook settings to enforce verification.');
  }
  let event = null;
  try { event = JSON.parse(raw || 'null'); } catch (_) { event = null; }
  const evType = String((event && event.type) || '').toLowerCase();
  const evData = event && event.data && typeof event.data === 'object' ? event.data : {};
  const recipients = Array.isArray(evData.to)
    ? evData.to
    : (evData.to ? [evData.to] : (evData.email ? [evData.email] : []));
  let suppressed = 0;
  if (evType === 'email.bounced' || evType === 'email.complained') {
    // Only HARD bounces suppress. Resend's bounce object carries the SES-style
    // type: Permanent (hard) / Transient (soft) / Undetermined — soft and
    // undetermined bounces are left alone (they may deliver next time).
    const bounceType = String((evData.bounce && (evData.bounce.type || evData.bounce.bounceType)) || evData.bounce_type || '').toLowerCase();
    const isSoftBounce = evType === 'email.bounced'
      && (bounceType === 'transient' || bounceType === 'soft' || bounceType === 'undetermined');
    if (!isSoftBounce) {
      const reason = evType === 'email.complained' ? 'complaint' : 'hard_bounce';
      for (const rcpt of recipients) {
        const done = await suppressEmail(rcpt, reason, 'resend_webhook');
        if (done) suppressed++;
      }
      if (suppressed > 0) {
        console.log('[Resend webhook]', evType, '→ suppressed', suppressed, 'recipient(s)');
      }
    }
  }
  sendJson(res, 200, { ok: true, suppressed });
}

/* ───────── Admin audit log ─────────
 * Append-only record of privileged admin actions (table: public.admin_audit_log,
 * migration 20260621130000). Call sites AWAIT logAdminAction inside their own
 * try/catch is unnecessary — this helper never throws — but the insert IS awaited
 * (NOT fire-and-forget) because a detached promise is killed when the serverless
 * function freezes after res.end(), which would silently drop the highest-value
 * rows (logins, impersonation). Awaiting adds a small, acceptable latency.
 */
const AUDIT_CRITICAL_ACTIONS = new Set([
  'admin_purge_all_users',
  'admin_reset_gp',
  'admin_impersonate',
  'admin_set_account_status_suspended'
]);

function clampAuditDetail(detail) {
  try {
    if (!detail || typeof detail !== 'object') return {};
    const s = JSON.stringify(detail);
    if (!s || s.length > 4000) return { truncated: true };
    return detail;
  } catch (_) {
    return {};
  }
}

// ctx = { email, role } of the acting admin (or null for pre-auth endpoints — then
// pass fields.actorEmail). action = a stable verb like 'admin_login_success'.
// fields = { targetType, targetId, detail, success, actorEmail }.
async function logAdminAction(req, ctx, action, fields = {}) {
  try {
    if (!isSupabaseDbConfigured()) return; // prod-only; local JSON path is unaudited by design
    let ip = null;
    try { ip = String(getClientIp(req) || '').slice(0, 64) || null; } catch (_) { ip = null; }
    const headers = (req && req.headers) || {};
    const row = {
      actor_email: ctx && ctx.email
        ? String(ctx.email).slice(0, 320)
        : (fields.actorEmail ? String(fields.actorEmail).slice(0, 320) : null),
      actor_role: ctx && ctx.role ? String(ctx.role).slice(0, 64) : null,
      action: String(action || 'unknown').slice(0, 96),
      target_type: fields.targetType ? String(fields.targetType).slice(0, 64) : null,
      target_id: fields.targetId != null ? String(fields.targetId).slice(0, 320) : null,
      detail: clampAuditDetail(fields.detail),
      ip,
      host: String(headers.host || '').slice(0, 255) || null,
      user_agent: String(headers['user-agent'] || '').slice(0, 512) || null,
      success: fields.success !== false
    };
    const result = await supabaseDbRequest('admin_audit_log', '', {
      method: 'POST',
      body: [row],
      headers: { Prefer: 'return=minimal' }
    });
    if (!result || !result.ok) {
      console.error('[audit] insert failed', result && result.status, action);
    }
    if (result && result.ok && row.success && AUDIT_CRITICAL_ACTIONS.has(row.action)) {
      await maybeAlertCriticalAction(row);
    }
  } catch (err) {
    console.error('[audit] logAdminAction error:', err && err.message);
  }
}

// Best-effort email alert to the owner on critical actions. Deduped per
// action+actor+target over a 5-minute window so a burst (e.g. impersonating
// several GPs) doesn't spam, while distinct targets still each alert.
async function maybeAlertCriticalAction(row) {
  try {
    if (!isEmailConfigured()) return;
    const to = String(process.env.AUDIT_ALERT_EMAIL || process.env.CEO_EMAIL || '').trim();
    if (!to) return;
    const dedupeKey = `auditalert:${row.action}:${row.actor_email || '?'}:${row.target_id || '*'}`;
    const existing = await getRuntimeKv(dedupeKey);
    if (existing && existing.value && Object.keys(existing.value).length) return;
    await setRuntimeKv(dedupeKey, { at: Date.now() }, Date.now() + 5 * 60 * 1000);
    const lines = [
      `Action: ${row.action}`,
      `By: ${row.actor_email || 'unknown'} (${row.actor_role || 'n/a'})`,
      row.target_id ? `Target: ${(row.target_type || '').trim()} ${row.target_id}`.trim() : null,
      `IP: ${row.ip || 'n/a'}   Host: ${row.host || 'n/a'}`,
      `Detail: ${JSON.stringify(row.detail || {})}`,
      `Time: ${new Date().toISOString()}`
    ].filter(Boolean);
    await sendEmail({
      to,
      subject: `[GP Link] Admin action: ${row.action}`,
      text: lines.join('\n')
    });
  } catch (err) {
    console.error('[audit] alert error:', err && err.message);
  }
}

function buildZoomCallInviteEmailHtml(gpFirstName, stageDisplay, bookingUrl, reason) {
  const escHtml = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const reasonBlock = (reason && String(reason).trim())
    ? '<div style="background:#f1f5f9;border-left:4px solid #2D8CFF;padding:12px 16px;margin:16px 0;border-radius:6px">'
      + '<div style="font-size:12px;font-weight:700;color:#2D8CFF;text-transform:uppercase;letter-spacing:.03em;margin-bottom:4px">Why we\'d like to meet</div>'
      + '<div style="color:#334155;font-size:14px;line-height:1.6">' + escHtml(String(reason).trim()).replace(/\n/g, '<br>') + '</div>'
      + '</div>'
    : '';
  return '<div style="font-family:sans-serif;max-width:560px;margin:0 auto;padding:24px">'
    + '<h2 style="color:#0f172a;font-size:20px">Zoom Assistance Call</h2>'
    + '<p style="color:#334155;font-size:14px;line-height:1.6">Hi ' + gpFirstName + ',</p>'
    + '<p style="color:#334155;font-size:14px;line-height:1.6">Your GP Link team thinks a short Zoom call would be the best way to guide you through your <strong>' + stageDisplay + '</strong> stage.</p>'
    + reasonBlock
    + '<p style="color:#334155;font-size:14px;line-height:1.6">Please pick a time that works for you:</p>'
    + '<div style="text-align:center;margin:24px 0">'
    + '<a href="' + bookingUrl + '" style="display:inline-block;padding:12px 28px;background:#2D8CFF;color:#fff;text-decoration:none;border-radius:8px;font-weight:700;font-size:14px">Book Your Time Slot</a>'
    + '</div>'
    + '<p style="color:#64748b;font-size:12px">If the button doesn\'t work, copy this link: ' + bookingUrl + '</p>'
    + '</div>';
}

/* ───────── Email confirmation via Resend ───────── */

async function sendEmailConfirmationViaResend(email) {
  if (!isEmailConfigured() || !SUPABASE_SERVICE_ROLE_KEY) return false;

  // Generate a confirmation link via Supabase Admin API
  const redirectTo = APP_BASE_URL + '/pages/signin?confirmed=true';
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 10000);
  try {
    const linkRes = await fetch(SUPABASE_URL + '/auth/v1/admin/generate_link', {
      method: 'POST',
      signal: controller.signal,
      headers: {
        apikey: SUPABASE_SERVICE_ROLE_KEY,
        Authorization: 'Bearer ' + SUPABASE_SERVICE_ROLE_KEY,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        type: 'signup',
        email: email,
        options: { redirect_to: redirectTo }
      })
    });
    const linkData = await linkRes.json().catch(() => ({}));
    const confirmUrl = linkData.action_link || linkData.properties && linkData.properties.action_link || '';
    if (!confirmUrl) {
      console.error('[email-confirm] No action_link returned from Supabase:', JSON.stringify(linkData).slice(0, 300));
      return false;
    }

    // Send via Resend
    const result = await sendEmail({
      to: email,
      subject: 'Verify your GP Link account',
      html: buildCareerEmailHtml({
        title: 'Verify your email',
        body: 'Thanks for signing up to GP Link! Please click the button below to verify your email address and activate your account.',
        ctaText: 'Verify Email',
        ctaUrl: confirmUrl,
        footer: 'If you didn\'t create a GP Link account, you can safely ignore this email. This link expires in 24 hours.'
      })
    });
    if (result.ok) {
      console.log('[email-confirm] Confirmation email sent to', email);
      return true;
    }
    console.error('[email-confirm] Resend send failed:', result.error);
    return false;
  } catch (err) {
    console.error('[email-confirm] Error:', err && err.message);
    return false;
  } finally {
    clearTimeout(timeout);
  }
}

/* ───────── Automated GP Email Notifications ───────── */

async function getGpEmailContext(userId) {
  if (!isSupabaseDbConfigured() || !userId) return null;
  const r = await supabaseDbRequest('user_profiles', 'select=email,first_name,last_name&user_id=eq.' + encodeURIComponent(userId) + '&limit=1');
  if (!r.ok || !Array.isArray(r.data) || !r.data[0]) return null;
  const p = r.data[0];
  return { email: p.email, firstName: p.first_name || '', lastName: p.last_name || '', name: ((p.first_name || '') + ' ' + (p.last_name || '')).trim() };
}

async function getGpEmailContextByCaseId(caseId) {
  if (!isSupabaseDbConfigured() || !caseId) return null;
  const cr = await supabaseDbRequest('registration_cases', 'select=user_id&id=eq.' + encodeURIComponent(caseId) + '&limit=1');
  if (!cr.ok || !Array.isArray(cr.data) || !cr.data[0]) return null;
  return getGpEmailContext(cr.data[0].user_id);
}

async function sendGpNotificationEmail(userId, subject, title, body, ctaText, ctaUrl, footer) {
  if (!isEmailConfigured()) return;
  const gp = await getGpEmailContext(userId);
  if (!gp || !gp.email) return;
  const nameVal = gp.firstName || 'there';
  const personalTitle = title.replace(/\{\{name\}\}/g, nameVal);
  const personalBody = body.replace(/\{\{name\}\}/g, nameVal);
  await sendEmail({
    to: gp.email,
    subject: subject.replace(/\{\{name\}\}/g, nameVal),
    html: buildCareerEmailHtml({
      title: personalTitle,
      body: personalBody,
      ctaText: ctaText || 'Go to Dashboard',
      ctaUrl: ctaUrl || APP_BASE_URL + '/pages/index.html',
      footer: footer || ''
    })
  }).catch((e) => console.error('[email-notify] Send failed:', e && e.error));
}

